<?php
require_once dirname(__DIR__) . '/einrichtung.php';
/* Gebäudewerke Ratgeber: listet alle Beiträge in diesem Ordner automatisch auf.
   Ein Beitrag erscheint, sobald eine HTML-Datei mit <meta name="artikel-datum"> hier liegt.
   Dateien, die mit _ beginnen (zum Beispiel die Vorlage), werden ignoriert. */
function gw_meta($s, $name) {
  if (preg_match('/<meta\s+name="' . preg_quote($name, '/') . '"\s+content="([^"]*)"/i', $s, $m)) return html_entity_decode($m[1], ENT_QUOTES, 'UTF-8');
  return '';
}
date_default_timezone_set('Europe/Berlin');
$gw_heute = date('Y-m-d');
$gw_beitraege = [];
foreach (glob(__DIR__ . '/*.html') as $gw_datei) {
  $gw_name = basename($gw_datei);
  if ($gw_name[0] === '_') continue;
  $gw_s = file_get_contents($gw_datei, false, null, 0, 20000);
  $gw_datum = gw_meta($gw_s, 'artikel-datum');
  if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $gw_datum)) continue;
  if ($gw_datum > $gw_heute) continue;   // geplante Beiträge erst ab ihrem Datum zeigen
  preg_match('/<h1[^>]*>(.*?)<\/h1>/s', file_get_contents($gw_datei), $gw_h1);
  $gw_beitraege[] = [
    'datei' => $gw_name, 'datum' => $gw_datum,
    'titel' => isset($gw_h1[1]) ? trim(strip_tags($gw_h1[1])) : $gw_name,
    'text' => gw_meta($gw_s, 'description'),
    'bild' => gw_meta($gw_s, 'artikel-bild'),
    'bildtext' => gw_meta($gw_s, 'artikel-bildtext'),
    'thema' => gw_meta($gw_s, 'artikel-thema'),
  ];
}
usort($gw_beitraege, function ($a, $b) { return strcmp($b['datum'], $a['datum']); });
function gw_e($t) { return htmlspecialchars($t, ENT_QUOTES, 'UTF-8'); }
?>
